import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * Builds the "Themes" sidebar items from the categories of the theme overview (`themes/index.md`).
 *
 * Each `## Category` of the overview becomes a collapsed group listing the themes it links to, in the same order, so
 * the overview stays the only place where a theme is categorized. The other pages of the folder (color schemes…)
 * follow the groups. Without categories, the folder is autogenerated as before.
 */
export function themesSidebar(docsDir) {
    const dir = join(docsDir, 'themes');
    const index = join(dir, 'index.md');
    if (!existsSync(index)) {
        return [{ autogenerate: { directory: 'themes' } }];
    }

    const groups = readFileSync(index, 'utf8')
        .split(/^## /m)
        .slice(1)
        .map((section) => ({
            label: section.split('\n', 1)[0].trim(),
            collapsed: true,
            items: [...new Set([...section.matchAll(/\]\(([\w-]+)\.md\)/g)].map(([, page]) => page))]
                .filter((page) => existsSync(join(dir, `${page}.md`)))
                .map((page) => `themes/${page}`),
        }))
        .filter((group) => group.items.length > 0);
    if (groups.length === 0) {
        return [{ autogenerate: { directory: 'themes' } }];
    }

    const grouped = new Set(groups.flatMap((group) => group.items));
    const others = readdirSync(dir)
        .filter((name) => name.endsWith('.md') && name !== 'index.md')
        .map((name) => `themes/${name.slice(0, -3)}`)
        .filter((slug) => !grouped.has(slug))
        .sort();

    return [{ label: 'Overview', slug: 'themes' }, ...groups, ...others];
}
